using Engine;
using Game;
using Game.Westworld;
using System.Text.Json;
using Westworld.Runtime.Core;
using Westworld.Decisions.Local;
internal sealed partial class ToolAgentScenario {
 bool IsNaturalMode=>ToolAgentGate.Mode=="natural";
 NaturalResourceAcquisitionLedger naturalLedger;Guid naturalWorld,naturalActor,naturalRequest;
 string naturalUnknown;int naturalLateDispatches;long naturalOriginRecords,naturalOriginListeners,naturalTransferListeners;
 readonly Dictionary<string,(ResourceTarget Target,double Time)> naturalVisible=new();
 readonly List<object> naturalObservations=[],naturalOrigins=[],naturalTransfers=[];
 readonly List<NaturalAttempt> naturalAttempts=[];readonly Dictionary<Guid,NaturalAttempt> naturalSources=[];NaturalAttempt naturalActive;
 Dictionary<int,int> naturalBaseline;
 sealed class NaturalAttempt {
  public Guid BindingId{get;init;}=Guid.NewGuid();public Guid RequestId{get;init;}public string Tool{get;init;}public Guid EvidenceId{get;init;}public ResourceTarget Target{get;init;}public double StartedAt{get;init;}
  public long? ReceiptSequence{get;set;}public Guid? RunId{get;set;}public string TerminalStatus{get;set;}public double? TerminalAt{get;set;}
 }
 Dictionary<int,int> NaturalInventory(){var i=p.ComponentMiner.Inventory;return Enumerable.Range(0,i.SlotsCount).Where(s=>i.GetSlotCount(s)>0).GroupBy(i.GetSlotValue).ToDictionary(g=>g.Key,g=>g.Sum(i.GetSlotCount));}
 long NaturalFailures()=>NaturalResourceOriginAudit.RecordFailures+NaturalResourceOriginAudit.ListenerFailures+NativeAcquisitionAudit.ListenerFailures;
 void SetupNatural(){if(!IsNaturalMode)return;naturalWorld=NativeAcquisitionAudit.IdentityFor(p.Project);naturalActor=NativeAcquisitionAudit.IdentityFor(p.Entity);naturalBaseline=NaturalInventory();naturalOriginRecords=NaturalResourceOriginAudit.RecordFailures;naturalOriginListeners=NaturalResourceOriginAudit.ListenerFailures;naturalTransferListeners=NativeAcquisitionAudit.ListenerFailures;naturalLedger=new(naturalWorld,naturalActor,naturalBaseline,NaturalFailures(),MonotonicSeconds);NaturalResourceOriginAudit.Recorded+=NaturalOrigin;NativeAcquisitionAudit.Recorded+=NaturalTransfer;
  ToolAgentGate.Log(new{kind="natural_scope",worldId=naturalWorld,nativeActorId=naturalActor,gatewaySessionId=gateway.SessionId,gatewayActorId=gateway.ActorId,seed=ToolAgentGate.WorldSeed,baselineInventory=naturalBaseline,terrainEdited=false,positionEdited=false,inventoryInjected=false,foodInjected=false,healthEdited=false});
 }
 void NaturalObserve(JsonElement observation){if(!IsNaturalMode)return;naturalVisible.Clear();if(!observation.TryGetProperty("visibleBlocks",out var blocks))return;foreach(var b in blocks.EnumerateArray().Take(128)){var c=b.GetProperty("cell");naturalVisible[b.GetProperty("reference").GetString()]=(new(naturalWorld,"block_drop",c.GetProperty("x").GetInt32(),c.GetProperty("y").GetInt32(),c.GetProperty("z").GetInt32(),b.GetProperty("value").GetInt32(),null),MonotonicSeconds);}}
 void BeginNatural(ToolDecisionStep step,Guid? candidate){if(!IsNaturalMode)return;if(foodStopTime.HasValue)naturalLateDispatches++;if(step.Tool!="act_Dig")return;
  if(naturalAttempts.Count>=128){naturalUnknown="attempt_capacity";return;}if(!step.Arguments.TryGetProperty("target",out var reference)||!naturalVisible.TryGetValue(reference.GetString(),out var seen)){naturalUnknown="dig_not_bound_to_current_visible_block";return;}
  var id=Guid.NewGuid();naturalLedger.ObserveTarget(id,seen.Target,seen.Time);naturalActive=new(){RequestId=candidate??naturalRequest,Tool=step.Tool,EvidenceId=id,Target=seen.Target,StartedAt=MonotonicSeconds};naturalAttempts.Add(naturalActive);naturalObservations.Add(new{evidenceId=id,target=seen.Target,observedAt=seen.Time,reference=reference.GetString()});
 }
 void BindNatural(ToolDecisionStep step,ToolReceipt receipt){if(!IsNaturalMode||step.Tool!="act_Dig"||naturalActive is null)return;naturalActive.ReceiptSequence=receipt.Sequence;if(receipt.State=="returned"&&receipt.Data.ValueKind==JsonValueKind.Object&&receipt.Data.TryGetProperty("runId",out var run)&&run.TryGetGuid(out var id))naturalActive.RunId=id;else naturalUnknown="dig_missing_native_run";if(receipt.State!="returned"){naturalActive.TerminalStatus="uncertain";naturalActive=null;}}
 void NaturalTerminal(ToolReceipt original,JsonElement actual){if(!IsNaturalMode||original.Tool!="act_Dig")return;var attempt=naturalAttempts.LastOrDefault(a=>a.ReceiptSequence==original.Sequence);if(attempt is null){naturalUnknown="unbound_dig_terminal";return;}
  if(!actual.TryGetProperty("runId",out var run)||!run.TryGetGuid(out var id)||id!=attempt.RunId){naturalUnknown="dig_terminal_run_mismatch";return;}attempt.TerminalStatus=Status(actual);attempt.TerminalAt=MonotonicSeconds;if(ReferenceEquals(attempt,naturalActive))naturalActive=null;
 }
 void NaturalOrigin(NaturalResourceOriginFact fact){if(!IsNaturalMode||fact.WorldId!=naturalWorld)return;var a=naturalActive;if(a is null||fact.Kind!="block_drop")return;var target=new ResourceTarget(fact.WorldId,fact.Kind,fact.CellX,fact.CellY,fact.CellZ,fact.OriginalBlockValue is int raw ? NaturalResourceAcquisitionLedger.ObservedBlockIdentity(raw) : null,fact.OriginEntityId);if(target!=a.Target)return;
  if(naturalOrigins.Count>=256){naturalUnknown="origin_capacity";return;}naturalLedger.Origin(a.EvidenceId,new(fact.EventId,fact.SourceId,target,fact.Value,fact.Count,fact.CreationGameTime,fact.GameTime,fact.MonotonicSeconds));naturalSources.TryAdd(fact.SourceId,a);naturalOrigins.Add(new{bindingId=a.BindingId,fact});ToolAgentGate.Log(new{kind="natural_origin_bound",bindingId=a.BindingId,fact,hostOnly=true});
 }
 void NaturalTransfer(NativeAcquisitionFact fact){if(!IsNaturalMode||fact.ActorId!=naturalActor&&!naturalSources.ContainsKey(fact.SourceId))return;if(naturalTransfers.Count>=256){naturalUnknown="transfer_capacity";return;}var id=Guid.NewGuid();naturalLedger.Transfer(new(id,fact.SourceId,fact.ActorId,fact.Value,fact.SourceBefore,fact.SourceAfter,fact.InventoryBefore,fact.InventoryAfter,fact.Method,fact.MonotonicSeconds));naturalTransfers.Add(new{eventId=id,fact});ToolAgentGate.Log(new{kind="natural_transfer",eventId=id,fact,hostOnly=true});}
 void TickNatural(){if(!IsNaturalMode)return;var drops=p.Project.FindSubsystem<SubsystemPickables>(true).Pickables;var sourceState=new Dictionary<Guid,(int Value,int Count)>();foreach(var drop in drops){var id=NativeAcquisitionAudit.IdentityFor(drop);if(naturalSources.ContainsKey(id)&&!drop.ToRemove)sourceState[id]=(drop.Value,drop.Count);}naturalLedger.Reconcile(NaturalInventory(),sourceState,NaturalFailures(),MonotonicSeconds);}
 int NaturalAiViewportCount()=>p.Project.FindSubsystem<SubsystemPlayers>(true).PlayersData.Count(d=>d.IsExternalActor&&d.GameWidget is not null);
 bool NaturalGoal()=>IsNaturalMode&&p.GameWidget is null&&NaturalAiViewportCount()==0&&naturalUnknown is null&&!naturalLedger.State.Unknown&&naturalLedger.State.Sources.Any(s=>s.Acquired>0&&naturalSources.TryGetValue(s.SourceId,out var a)&&a.TerminalStatus=="succeeded"&&a.RunId.HasValue);
 void FinishNatural(){if(!IsNaturalMode)return;try{TickNatural();bool invalidatedSuccess=Passed&&!NaturalGoal();if(invalidatedSuccess)Passed=false;ToolAgentGate.Log(new{kind="natural_resource_evidence",schema=1,worldId=naturalWorld,nativeActorId=naturalActor,gatewaySessionId=gateway.SessionId,gatewayActorId=gateway.ActorId,seed=ToolAgentGate.WorldSeed,aiViewportCount=NaturalAiViewportCount(),actorGameWidgetNull=p.GameWidget is null,fixture=new{terrainEdited=false,positionEdited=false,inventoryInjected=false,foodInjected=false,healthEdited=false},baselineInventory=naturalBaseline,actualInventory=NaturalInventory(),observations=naturalObservations,attempts=naturalAttempts,origins=naturalOrigins,transfers=naturalTransfers,ledger=naturalLedger.State,unknownReason=naturalUnknown,auditFailures=new{originRecordBefore=naturalOriginRecords,originRecordAfter=NaturalResourceOriginAudit.RecordFailures,originListenerBefore=naturalOriginListeners,originListenerAfter=NaturalResourceOriginAudit.ListenerFailures,transferListenerBefore=naturalTransferListeners,transferListenerAfter=NativeAcquisitionAudit.ListenerFailures},shutdown=new{stopTime=foodStopTime,drainedTime=foodDrainedTime,idle=foodDrainedTime.HasValue,lateDispatches=naturalLateDispatches},animalAttributionSupported=false,note="Block-origin acquisition only; source events do not by themselves prove harvesting actor. Actual Dig run must succeed. No resource coordinates from this host audit enter model prompts."});if(invalidatedSuccess)throw new InvalidOperationException("Natural provenance invalidated during drain");}finally{NaturalResourceOriginAudit.Recorded-=NaturalOrigin;NativeAcquisitionAudit.Recorded-=NaturalTransfer;}}
}
